<?php
declare(strict_types=1);
function az_mail_enabled(): bool { return (bool)(az_env('SMTP_HOST')&&az_env('SMTP_USER')&&az_env('SMTP_PASS')); }
function az_telegram_enabled(): bool { return (bool)(az_env('TELEGRAM_BOT_TOKEN')&&az_env('TELEGRAM_CHAT_ID')); }
function az_mail($to,string $subject,string $html): bool {
    $to=array_values(array_filter(is_array($to)?$to:[$to],fn($s)=>az_email(trim((string)$s)))); if(!az_mail_enabled()||!$to) return false;
    $host=az_env('SMTP_HOST'); $port=(int)az_env('SMTP_PORT','465'); $from=az_env('MAIL_FROM',az_env('SMTP_USER')); preg_match('/<([^>]+)>/',$from,$m); $fromAddr=$m[1]??$from;
    if(!az_email($fromAddr)||preg_match('/[\r\n]/',$from.$subject)) throw new RuntimeException('Invalid email headers');
    $context=stream_context_create(['ssl'=>['verify_peer'=>true,'verify_peer_name'=>true,'peer_name'=>$host]]); $socket=stream_socket_client(($port===465?'ssl://':'tcp://').$host.':'.$port,$errno,$errstr,10,STREAM_CLIENT_CONNECT,$context); if(!$socket) throw new RuntimeException('SMTP connection failed'); stream_set_timeout($socket,15);
    $read=function(int $expected)use($socket){ $last=''; while(($line=fgets($socket,2048))!==false) { $last=$line; if(preg_match('/^\d{3} /',$line)) break; } if((int)substr($last,0,3)!==$expected) throw new RuntimeException('SMTP rejected a command'); };
    $cmd=function(string $line,int $status)use($socket,$read){ if(fwrite($socket,$line."\r\n")===false) throw new RuntimeException('SMTP write failed'); $read($status); };
    try { $read(220); $cmd('EHLO aarzu',250); if($port!==465) { $cmd('STARTTLS',220); if(!stream_socket_enable_crypto($socket,true,STREAM_CRYPTO_METHOD_TLS_CLIENT)) throw new RuntimeException('SMTP TLS failed'); $cmd('EHLO aarzu',250); } $cmd('AUTH LOGIN',334); $cmd(base64_encode(az_env('SMTP_USER')),334); $cmd(base64_encode(az_env('SMTP_PASS')),235); $cmd('MAIL FROM:<'.$fromAddr.'>',250); foreach($to as $recipient) $cmd('RCPT TO:<'.trim($recipient).'>',250); $cmd('DATA',354);
        $boundary='aarzu'.bin2hex(random_bytes(12)); $encoded='=?UTF-8?B?'.base64_encode($subject).'?='; $headers=['From: '.$from,'To: '.implode(', ',$to),'Subject: '.$encoded,'Date: '.gmdate('D, d M Y H:i:s').' +0000','MIME-Version: 1.0','Content-Type: multipart/alternative; boundary="'.$boundary.'"'];
        $message=implode("\r\n",$headers)."\r\n\r\n--$boundary\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Transfer-Encoding: base64\r\n\r\n".chunk_split(base64_encode(strip_tags($html)),76,"\r\n")."--$boundary\r\nContent-Type: text/html; charset=utf-8\r\nContent-Transfer-Encoding: base64\r\n\r\n".chunk_split(base64_encode($html),76,"\r\n")."--$boundary--\r\n"; $cmd($message."\r\n.",250); fwrite($socket,"QUIT\r\n");
    } finally { fclose($socket); } return true;
}
function az_telegram(string $text): bool {
    if(!az_telegram_enabled()) return false; $ch=curl_init('https://api.telegram.org/bot'.az_env('TELEGRAM_BOT_TOKEN').'/sendMessage'); curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode(['chat_id'=>az_env('TELEGRAM_CHAT_ID'),'text'=>$text,'parse_mode'=>'HTML','disable_web_page_preview'=>true],AZ_JSON),CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>15]); $result=curl_exec($ch); $status=curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch); if(!$result||$status!==200) throw new RuntimeException('Telegram notification failed'); return true;
}
function az_mail_shell(string $title,string $inner): string {
    $s=az_store(); $site=rtrim(az_env('SITE_URL'),'/'); $logo=$site?'<img src="'.az_h($site).'/brand/aarzu-logo.png" alt="Aarzu" width="180" style="display:block;margin:0 auto 6px">':'<div style="font:600 28px Georgia,serif;letter-spacing:8px;color:#1E1324">AARZU</div>';
    return '<!doctype html><html><body style="margin:0;background:#FFF8EF;font-family:Helvetica,Arial,sans-serif;color:#1E1324"><div style="height:6px;background:linear-gradient(90deg,#D6246E,#F26B1D,#F2A900,#0FA3A3,#1C2A6B)"></div><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:28px 14px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;background:#fff;border-radius:18px;overflow:hidden"><tr><td style="padding:28px 28px 8px;text-align:center">'.$logo.'<div style="font-size:12px;letter-spacing:3px;color:#A3164F;text-transform:uppercase">'.az_h($title).'</div></td></tr><tr><td style="padding:8px 28px 28px;font-size:15px;line-height:1.6">'.$inner.'</td></tr><tr><td style="padding:18px 28px;background:#1E1324;color:#F7E7C1;font-size:12px;text-align:center">'.az_h($s['name']).' · WhatsApp +'.az_h($s['contact']['whatsapp']).' · '.az_h($s['contact']['email']).'<br>آپ کی آرزو، ہماری ذمہ داری</td></tr></table></td></tr></table></body></html>';
}
function az_order_table(array $o): string {
    $html='<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px">'; foreach($o['items'] as $i) $html.='<tr><td style="padding:8px 0;border-bottom:1px solid #f0e6da">'.az_h($i['title']).'<br><span style="color:#8A7C8E;font-size:13px">'.az_h($i['size']).' × '.$i['qty'].(!empty($i['addons'])?' · '.az_h(implode(', ',array_column($i['addons'],'label'))):'').(!empty($i['meta']['summary'])?' · '.az_h($i['meta']['summary']):'').'</span></td><td style="text-align:right">'.az_rs($i['line']).'</td></tr>';
    $rows=[['label'=>'Subtotal','amount'=>$o['subtotal']]]; foreach($o['discounts'] as $d) $rows[]=['label'=>$d['label'],'amount'=>-$d['amount']]; $rows[]=['label'=>'Delivery','amount'=>$o['shipping']]; foreach($o['credits']??[] as $c) $rows[]=['label'=>$c['label'],'amount'=>-$c['amount']]; $rows[]=['label'=>'Total','amount'=>$o['total']]; foreach($rows as $r) $html.='<tr><td style="padding:4px 0">'.az_h($r['label']).'</td><td style="text-align:right">'.az_rs($r['amount']).'</td></tr>'; return $html.'</table>';
}
function az_safe_notify(callable $fn): bool { try { return (bool)$fn(); } catch(Throwable $e) { error_log('[notify] '.$e->getMessage()); return false; } }
function az_notify(array $o,string $event): void {
    $c=$o['customer']; $s=az_store(); $site=rtrim(az_env('SITE_URL'),'/'); $table=az_order_table($o); $first=az_h(explode(' ',$c['name'])[0]); $track=$site?'<p style="text-align:center;margin:22px 0"><a href="'.az_h($site).'/track?id='.az_h($o['id']).'" style="background:#D6246E;color:#fff;text-decoration:none;padding:12px 26px;border-radius:999px;font-weight:600">Track your order</a></p>':'';
    if($event==='placed') {
        $owners=array_map('trim',explode(',',az_env('ORDER_ALERT_EMAIL'))); az_safe_notify(fn()=>az_mail($owners,'🛍️ New order '.$o['id'].' · '.az_rs($o['total']).' · '.$c['city'],az_mail_shell('New order','<p><b>'.az_h($c['name']).'</b> · +'.az_h($c['phone']).' · '.az_h($c['email']).'<br>'.az_h($c['address']).', '.az_h($c['city']).'</p><p>Payment: '.az_h(AZ_PAYMENTS[$o['payment']]).'</p>'.$table.'<p><a href="'.az_h($site).'/admin">Open the admin dashboard</a></p>')));
        az_safe_notify(fn()=>az_telegram('🛍️ <b>New order '.az_h($o['id']).'</b> · '.az_rs($o['total'])."\n".az_h($c['name']).' · '.az_h($c['city']).' · +'.az_h($c['phone'])."\n".az_h(AZ_PAYMENTS[$o['payment']])."\n".implode("\n",array_map(fn($i)=>'• '.az_h(az_item_text($i)),$o['items']))));
        $payment=$o['payment']==='cod'?'<p>Please keep <b>'.az_rs($o['total']).'</b> ready in cash for the rider.</p>':'<p style="background:#FFF1D6;padding:14px;border-radius:12px"><b>Next step: payment.</b><br>'.nl2br(az_h($s['payments'][$o['payment']]['details']??"We'll WhatsApp you our account details shortly.")).'<br>Please send a screenshot of the transfer on WhatsApp with order number <b>'.az_h($o['id']).'</b>.</p>';
        $subject="Shukriya! We've received your Aarzu order ".$o['id']; $title='Order received'; $body='<p>Assalam o Alaikum '.$first.',</p><p>Thank you for shopping with Aarzu! We have received your order <b>'.az_h($o['id']).'</b> and our team will confirm it on WhatsApp shortly.</p>'.$table.$payment.'<p>Delivering to: '.az_h($c['address']).', '.az_h($c['city']).'</p>'.$track;
    } else {
        if($event==='returned') az_safe_notify(fn()=>az_telegram('↩️ Order '.az_h($o['id']).' was refused/returned ('.az_h($c['city']).', +'.az_h($c['phone']).')'));
        $messages=['confirmed'=>['Your Aarzu order '.$o['id'].' is confirmed','Order confirmed','<p>Assalam o Alaikum '.$first.', your order <b>'.az_h($o['id']).'</b> is confirmed and being prepared with love.</p>'.$track], 'dispatched'=>['Your Aarzu order '.$o['id'].' is on its way 🚚','On its way','<p>Good news '.$first.'! Your order <b>'.az_h($o['id']).'</b> has left our studio'.(!empty($o['courier'])?' with <b>'.az_h($o['courier']).'</b>':'').'.</p>'.(!empty($o['tracking'])?'<p style="font-size:18px;text-align:center">Tracking number: <b>'.az_h($o['tracking']).'</b></p>':'').($o['payment']==='cod'?'<p>Please keep <b>'.az_rs($o['total']).'</b> ready for the rider.</p>':'').$track], 'delivered'=>['Delivered! We hope you love it, '.explode(' ',$c['name'])[0],'Delivered','<p>Your order <b>'.az_h($o['id']).'</b> has been delivered. We hope it feels like a wish come true. 💫</p><p>If anything is not perfect, exchanges are easy within '.$s['returnDays'].' days. Just WhatsApp us.</p>'], 'cancelled'=>['Your Aarzu order '.$o['id'].' was cancelled','Order cancelled','<p>Your order <b>'.az_h($o['id']).'</b> has been cancelled. If this is unexpected, please WhatsApp us on +'.az_h($s['contact']['whatsapp']).'.</p>']];
        if(!isset($messages[$event])) return; [$subject,$title,$body]=$messages[$event];
    }
    if(!empty($c['email'])) az_safe_notify(fn()=>az_mail($c['email'],$subject,az_mail_shell($title,$body)));
}
function az_restock_notify(array $product,array $due): void {
    $ok=[]; $tried=[]; $site=rtrim(az_env('SITE_URL'),'/');
    foreach($due as $r) if(!empty($r['email'])&&!isset($tried[$r['email']])) { $tried[$r['email']]=true; $html=az_mail_shell('Back in stock','<p>Assalam o Alaikum,</p><p>Good news! <b>'.az_h($product['title']).'</b>'.(!$r['oneSize']?' in size <b>'.az_h($r['size']).'</b>':'').' is back in stock at Aarzu.</p><p>Pieces can sell out again, so if you would like it, it is best to order soon.</p><p><a href="'.az_h($site).'/product/'.rawurlencode($product['slug']).'">Shop it now</a></p>'); if(az_safe_notify(fn()=>az_mail($r['email'],'Back in stock: '.$product['title'],$html))) $ok[$r['email']]=true; }
    if($ok) { az_open(); $list=az_db('restock'); $ids=array_column($due,'id'); foreach($list as &$r) if(in_array($r['id'],$ids,true)&&isset($ok[$r['email']])) $r['emailedAt']=az_now(); unset($r); az_set('restock',$list); az_flush(); az_release(); }
    az_safe_notify(fn()=>az_telegram('🔔 <b>Back in stock</b>: '.az_h($product['title'])."\n".count($due).' people asked to hear about it. '.count($ok).' emailed. Follow up from Admin → Restock requests.'));
}
